      "additionalProperties": false,
      "required": ["order_value", "currency", "unit", "client", "order_type", "execution_period"],
      "properties": {
        "order_value": { "$ref": "#/$defs/order_value" },
        "currency": { "$ref": "#/$defs/currency" },
        "unit": { "$ref": "#/$defs/unit" },
        "client": { "$ref": "#/$defs/client" },
        "order_type": { "$ref": "#/$defs/order_type" },
        "execution_period": { "type": ["string", "null"], "minLength": 1 }
      },
      "allOf": [{ "$ref": "#/$defs/value_triplet" }]
    },
    "additional_order": {
      "type": "object",
      "additionalProperties": false,
      "required": ["order_value", "currency", "unit", "client", "evidence"],
      "properties": {
        "order_value": { "$ref": "#/$defs/order_value" },
        "currency": { "$ref": "#/$defs/currency" },
        "unit": { "$ref": "#/$defs/unit" },
        "client": { "$ref": "#/$defs/client" },
        "evidence": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "order_value": { "$ref": "#/$defs/quote" },
            "currency": { "$ref": "#/$defs/quote" },
            "unit": { "$ref": "#/$defs/quote" },
            "client": { "$ref": "#/$defs/quote" }
          }
        }
      },
      "allOf": [{ "$ref": "#/$defs/value_triplet" }]
    },
    "top_evidence": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "company": { "$ref": "#/$defs/quote" },
        "announcement_date": { "$ref": "#/$defs/quote" },
        "order_value": { "$ref": "#/$defs/quote" },
        "currency": { "$ref": "#/$defs/quote" },
        "unit": { "$ref": "#/$defs/quote" },
        "client": { "$ref": "#/$defs/quote" },
        "order_type": { "$ref": "#/$defs/quote" },
        "execution_period": { "$ref": "#/$defs/quote" }
      }
    }
  }
}

