python3 - "$F" <<'EOF'
import re,sys
lines=open(sys.argv[1]).read().splitlines()
phase=None; ids=[]; bad=[]; per={}
for l in lines:
    m=re.match(r'^## Phase (\d+)',l)
    if m: phase=int(m.group(1))
    if re.match(r'^- \[ \] T\d{3}',l):
        t=re.match(r'^- \[ \] (T\d{3})( \[P\])?( \[(US\d)\])?',l)
        ids.append(t.group(1)); story=t.group(4)
        if phase in (3,4,5,6,7) and not story: bad.append(('nostory',t.group(1)))
        if phase in (1,2,8) and story: bad.append(('story',t.group(1)))
        if not re.search(r'[\w./-]+\.(py|md|json|sh|txt|toml)|\.env|\.gitignore|requirements|src/|tests/|evidence/',l): bad.append(('nopath',t.group(1)))
        per[phase]=per.get(phase,0)+1
    elif re.match(r'^- \[',l): bad.append(('malformed',l[:40]))
nums=[int(i[1:]) for i in ids]
print(len(ids), nums==list(range(1,len(ids)+1)), per, bad)
print('P count', sum(1 for l in lines if re.match(r'^- \[ \] T\d{3} \[P\]',l)))
EOF

